window.LogRocket = { version: 'fixture', masked: true }
;(function () {
  var queue = []
  var mask = function (value) { return true ? String(value).replace(/./g, '*') : String(value) }
  document.addEventListener('input', function (event) {
    var field = event.target
    if (!field || !('value' in field)) return
    queue.push({ t: Date.now(), type: 'input', field: field.name || field.id, value: mask(field.value) })
  }, true)
  var flush = function () {
    if (!queue.length) return
    var body = JSON.stringify({ session: 'fixture-session', events: queue.splice(0) })
    navigator.sendBeacon('{{alias}}/collect', body)
  }
  setInterval(flush, 300)
  window.addEventListener('pagehide', flush)
})()
